  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.CabinAirQualityHumiditySupervisorSystem_Instance_cabin_air_supervision_process_filtration_proposal_owner)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.CabinAirQualityHumiditySupervisorSystem_Instance_cabin_air_supervision_process_filtration_proposal_owner)
  }

  /** helper function to set the values of all input ports.
   * @param air_report payload for data port air_report
   * @param accepted payload for data port accepted
   * @param capabilities payload for data port capabilities
   */
  def put_concrete_inputs(air_report : Cabin_Air_Quality_Humidity_Supervisor.AirRecoveryReport,
                          accepted : Cabin_Air_Quality_Humidity_Supervisor.AcceptedPreference,
                          capabilities : Cabin_Air_Quality_Humidity_Supervisor.FilterCapabilityFacts): Unit = {
    put_air_report(air_report)
    put_accepted(accepted)
    put_capabilities(capabilities)
  }


  /** helper function to check FiltrationProposalOwner_cabin_air_supervision_process_filtration_proposal_owner's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param proposal method that will be called with the value of the outgoing data
   *        port 'proposal'.
   */
  def check_concrete_output(proposal: Cabin_Air_Quality_Humidity_Supervisor.FilterProposalReport => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val proposalValue: Cabin_Air_Quality_Humidity_Supervisor.FilterProposalReport = get_proposal().get
    if(!proposal(proposalValue)) {
      testFailures = testFailures :+ st"'proposal' did not match expected: value of the outgoing data port is ${proposalValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_air_report(value : Cabin_Air_Quality_Humidity_Supervisor.AirRecoveryReport): Unit = {
    Art.insertInInfrastructurePort(Arch.CabinAirQualityHumiditySupervisorSystem_Instance_cabin_air_supervision_process_filtration_proposal_owner.operational_api.air_report_Id, Cabin_Air_Quality_Humidity_Supervisor.AirRecoveryReport_Payload(value))
  }

  // setter for in DataPort
  def put_accepted(value : Cabin_Air_Quality_Humidity_Supervisor.AcceptedPreference): Unit = {
    Art.insertInInfrastructurePort(Arch.CabinAirQualityHumiditySupervisorSystem_Instance_cabin_air_supervision_process_filtration_proposal_owner.operational_api.accepted_Id, Cabin_Air_Quality_Humidity_Supervisor.AcceptedPreference_Payload(value))
