  // setter for in DataPort
  def put_capabilities(value : Cabin_Air_Quality_Humidity_Supervisor.FilterCapabilityFacts): Unit = {
    Art.insertInInfrastructurePort(Arch.CabinAirQualityHumiditySupervisorSystem_Instance_cabin_air_supervision_process_filtration_proposal_owner.operational_api.capabilities_Id, Cabin_Air_Quality_Humidity_Supervisor.FilterCapabilityFacts_Payload(value))
  }

  // getter for out DataPort
  def get_proposal(): Option[Cabin_Air_Quality_Humidity_Supervisor.FilterProposalReport] = {
    val value: Option[Cabin_Air_Quality_Humidity_Supervisor.FilterProposalReport] = get_proposal_payload() match {
      case Some(Cabin_Air_Quality_Humidity_Supervisor.FilterProposalReport_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port proposal.  Expecting 'Cabin_Air_Quality_Humidity_Supervisor.FilterProposalReport_Payload' but received ${v}")
      case _ => None[Cabin_Air_Quality_Humidity_Supervisor.FilterProposalReport]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_proposal_payload(): Option[Cabin_Air_Quality_Humidity_Supervisor.FilterProposalReport_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.CabinAirQualityHumiditySupervisorSystem_Instance_cabin_air_supervision_process_filtration_proposal_owner.initialization_api.proposal_Id).asInstanceOf[Option[Cabin_Air_Quality_Humidity_Supervisor.FilterProposalReport_Payload]]
  }

